toolScript:
(() => {
  let observer = null;
  let stressWorker = null;
  let isStressActive = false;
  const history = [];
  const MAX_HISTORY = 30;

  const compatBanner = document.getElementById('cp-compat-banner');
  const compatStatus = document.getElementById('cp-compat-status');
  const gaugeCircle = document.getElementById('cp-gauge-circle');
  const stateLabel = document.getElementById('cp-state-label');
  const scoreLabel = document.getElementById('cp-score-label');
  const stateTitle = document.getElementById('cp-state-title');
  const stateDesc = document.getElementById('cp-state-desc');
  const riskVal = document.getElementById('cp-risk-val');
  const readingsCount = document.getElementById('cp-readings-count');
  const recommendation = document.getElementById('cp-recommendation');
  const stressBtn = document.getElementById('cp-stress-btn');
  const stopBtn = document.getElementById('cp-stop-btn');
  const canvas = document.getElementById('cp-timeline-canvas');
  const ctx = canvas.getContext('2d');

  function resizeCanvas() {
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * (window.devicePixelRatio || 1);
    canvas.height = rect.height * (window.devicePixelRatio || 1);
  }
  window.addEventListener('resize', resizeCanvas);
  resizeCanvas();

  const STATE_CONFIG = {
    nominal: {
      color: '#10b981',
      score: 100,
      title: 'Optimal Thermal Equilibrium',
      desc: 'System is operating within optimal thermal and power boundaries. Maximum Turbo Boost frequencies available.',
      risk: 'Low',
      riskColor: 'text-emerald-600',
      recom: 'Safe to execute high-intensity rendering, compilation, or AI inference workloads without throttling risk.'
    },
    fair: {
      color: '#3b82f6',
      score: 75,
      title: 'Moderate Workload Pressure',
      desc: 'System is handling sustained computation. Fans may be spinning up, but frequency throttling is not active.',
      risk: 'Moderate',
      riskColor: 'text-blue-600',
      recom: 'Normal operating envelope. Workloads proceed at target framerates without degradation.'
    },
    serious: {
      color: '#f59e0b',
      score: 40,
      title: 'Elevated Thermal Pressure',
      desc: 'Thermal junction or power delivery limits are approaching. CPU scheduler may throttle background worker threads.',
      risk: 'High',
      riskColor: 'text-amber-600',
      recom: 'Consider lowering render resolution, pausing unneeded background tasks, or checking laptop ventilation.'
    },
    critical: {
      color: '#f43f5e',
      score: 10,
      title: 'Critical Hardware Throttling',
      desc: 'Hardware protection thresholds triggered. Significant CPU down-clocking active to prevent thermal runaway.',
      risk: 'Critical',
      riskColor: 'text-rose-600',
      recom: 'Immediately reduce compute intensity, verify fan operation, and allow hardware to cool down.'
    }
  };

  function applyState(stateStr) {
    const key = (stateStr || 'nominal').toLowerCase();
    const cfg = STATE_CONFIG[key] || STATE_CONFIG.nominal;

    history.push(cfg.score);
    if (history.length > MAX_HISTORY) history.shift();

    stateLabel.textContent = key.toUpperCase();
    scoreLabel.textContent = `${cfg.score}% Score`;
    stateTitle.textContent = cfg.title;
    stateDesc.textContent = cfg.desc;
    riskVal.textContent = cfg.risk;
    riskVal.className = `text-sm font-bold block mt-1 ${cfg.riskColor}`;
    recommendation.textContent = cfg.recom;
    gaugeCircle.style.borderColor = cfg.color;
    readingsCount.textContent = String(history.length);

    drawTimeline();
  }

  function drawTimeline() {
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    // Background grid
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, h * 0.25); ctx.lineTo(w, h * 0.25);
    ctx.moveTo(0, h * 0.5); ctx.lineTo(w, h * 0.5);
    ctx.moveTo(0, h * 0.75); ctx.lineTo(w, h * 0.75);
    ctx.stroke();

    if (history.length < 2) return;

    const step = w / (MAX_HISTORY - 1);
    ctx.beginPath();
    for (let i = 0; i < history.length; i++) {
      const val = history[i];
      const x = i * step;
      const y = h - (val / 100) * (h * 0.8) - (h * 0.1);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.strokeStyle = '#38bdf8';
    ctx.lineWidth = 2 * (window.devicePixelRatio || 1);
    ctx.stroke();
  }

  // Check W3C PressureObserver
  if (typeof window !== 'undefined' && 'PressureObserver' in window) {
    compatStatus.textContent = 'Active: W3C PressureObserver API Connected';
    compatBanner.className = 'p-4 rounded-2xl bg-emerald-50 border border-emerald-200 text-emerald-950 text-xs flex flex-wrap items-center justify-between gap-3';

    try {
      observer = new window.PressureObserver((records) => {
        if (records.length > 0) {
          applyState(records[records.length - 1].state);
        }
      }, { sampleInterval: 1000 });
      observer.observe('cpu');
    } catch (e) {
      compatStatus.textContent = 'PressureObserver permission restricted. Running simulated baseline.';
      startSimulation();
    }
  } else {
    compatStatus.textContent = 'Compute Pressure API available on Chromium desktop (Chrome 115+). Running simulated hardware profile.';
    compatBanner.className = 'p-4 rounded-2xl bg-amber-50 border border-amber-200 text-amber-950 text-xs flex flex-wrap items-center justify-between gap-3';
    startSimulation();
  }

  function startSimulation() {
    setInterval(() => {
      if (!isStressActive) {
        // Minor natural baseline jitter between nominal and fair
        const rand = Math.random();
        applyState(rand > 0.85 ? 'fair' : 'nominal');
      }
    }, 1500);
  }

  // Stress testing worker
  stressBtn.addEventListener('click', () => {
    isStressActive = true;
    stressBtn.classList.add('hidden');
    stopBtn.classList.remove('hidden');
    applyState('serious');

    const workerBlob = new Blob([`
      let running = true;
      self.onmessage = (e) => { if (e.data === 'stop') running = false; };
      function work() {
        if (!running) return;
        let count = 0;
        for (let i = 0; i < 20000000; i++) { count += Math.sqrt(i); }
        setTimeout(work, 50);
      }
      work();
    `], { type: 'application/javascript' });

    stressWorker = new Worker(URL.createObjectURL(workerBlob));

    // Elevate simulated pressure if non-Chromium
    setTimeout(() => {
      if (isStressActive) applyState('critical');
    }, 4000);
  });

  stopBtn.addEventListener('click', () => {
    isStressActive = false;
    if (stressWorker) {
      stressWorker.postMessage('stop');
      stressWorker.terminate();
      stressWorker = null;
    }
    stopBtn.classList.add('hidden');
    stressBtn.classList.remove('hidden');
    applyState('nominal');
  });

  applyState('nominal');
})();
